/**
 * Temporary (DEMO) jewelry catalog - schema v1.
 *
 * Two files:
 * - the OVERRIDES file (committed, human-reviewed): which source images become
 *   which demo products, their category, a neutral display title, filter tags and
 *   a synthetic price. Filenames only - no images.
 * - the CATALOG file (generated by the importer, never committed): products plus
 *   content-addressed image assets, one numbered version per import.
 *
 * Demo data rules enforced here:
 * - ids are DEMO-<RNG|EAR|NCK|SET>-NNN and stable (never derived from images);
 * - titles may not make material / gemstone / authenticity claims;
 * - tags come from a fixed visual vocabulary (colour, shape, style);
 * - prices are synthetic and must be repeated-digit values (1111, 2222, ...), so a
 *   realistic-looking price can never slip in by accident;
 * - material, gemstone, sizes and description are always null in v1.
 */

export const OVERRIDES_SCHEMA = "thegemsutra.catalog-overrides";
export const CATALOG_SCHEMA = "thegemsutra.catalog";
export const SUPPORTED_VERSIONS = [1] as const;

export const CATEGORIES = {
  rings: { label: "Rings", prefix: "RNG" },
  earrings: { label: "Earrings", prefix: "EAR" },
  necklaces: { label: "Necklaces & Pendants", prefix: "NCK" },
  sets: { label: "Bridal Sets", prefix: "SET" },
} as const;
export type CategoryCode = keyof typeof CATEGORIES;

/** Visual-only filter vocabulary. Describes what an image looks like, not what it is made of. */
export const TAGS = {
  colour: ["blue", "aqua", "red", "green", "purple", "pink", "white", "champagne", "multi"],
  shape: ["round", "oval", "pear", "heart", "marquise", "cushion", "rectangular", "teardrop", "circle", "crescent", "geometric"],
  style: ["halo", "solitaire", "three-stone", "split-shank", "twisted", "floral", "leaf", "hoop", "drop", "stud", "spiral", "pendant", "station", "layered", "choker", "collar", "bar", "statement", "minimal", "vintage", "bridal"],
} as const;
export const ALL_TAGS: ReadonlySet<string> = new Set(Object.values(TAGS).flat());

/**
 * Words that would turn a demo title into an unverified factual claim
 * (metal, purity, gemstone, authenticity, certification).
 */
export const CLAIM_WORDS = [
  "gold", "golden", "silver", "sterling", "platinum", "rhodium", "vermeil", "plated", "karat", "carat", "ct",
  "diamond", "diamonds", "sapphire", "ruby", "emerald", "amethyst", "topaz", "morganite", "aquamarine", "pearl", "pearls",
  "crystal", "crystals", "gemstone", "gem", "cabochon", "enamel", "genuine", "natural", "real", "certified", "solid", "lab",
  "moissanite", "zirconia", "cz", "authentic", "hallmarked", "pave", "pavé",
];
const CLAIM_RE = new RegExp(`(^|[^a-z])(${CLAIM_WORDS.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})([^a-z]|$)|\\d+\\s*k\\b`, "i");

export type Severity = "error" | "warning" | "info";
export interface Issue {
  severity: Severity;
  field: string;
  message: string;
}

export interface OverrideProduct {
  id: string;
  category: CategoryCode;
  title: string;
  tags: string[];
  /** Synthetic price in PKR (repeated digits only). */
  price: number;
  /** Source images, relative to a source root ("Rings/Foo.jpg"); first = primary, then gallery order. */
  images: string[];
  /** Internal review notes, e.g. "Replace: checkerboard background baked into the image". */
  reviewNotes?: string[];
}

export interface Overrides {
  schema: typeof OVERRIDES_SCHEMA;
  schemaVersion: 1;
  dataset: string;
  /** Source images that must never be used (mood boards, third-party branding, ...). */
  exclude?: { file: string; reason: string }[];
  /** Editorial/lifestyle images: recorded, never attached to a product in v1. */
  lifestyle?: string[];
  products: OverrideProduct[];
}

export interface CatalogAsset {
  id: string; // img_<first 16 hex of sha256>
  sha256: string;
  /** Source path relative to its source root. Kept in the local catalog file only; never served. */
  source: string;
  width: number;
  height: number;
  usage: "product" | "lifestyle";
  /** Generated variants (WebP), relative to the output folder. */
  variants: { card: string; full: string };
}

export interface CatalogImage {
  asset: string;
  role: "primary" | "gallery";
  order: number;
  alt: string;
}

export interface CatalogProduct {
  id: string;
  slug: string;
  status: "demo";
  kind: "catalog";
  category: CategoryCode;
  title: string;
  tags: string[];
  description: null;
  material: null;
  gemstone: null;
  sizes: null;
  price: { amount: number; currency: "PKR"; synthetic: true };
  availability: "not-for-sale";
  images: CatalogImage[];
  /** Internal review notes carried from the overrides (shown on demo pages, never product copy). */
  reviewNotes: string[];
}

export interface Catalog {
  schema: typeof CATALOG_SCHEMA;
  schemaVersion: 1;
  dataset: string;
  environment: "demo";
  version: string; // v0001
  createdAt: string;
  products: CatalogProduct[];
  assets: CatalogAsset[];
}

/** What the image service serves to the storefront: no source paths, no hashes. */
export interface PublicCatalog {
  schema: typeof CATALOG_SCHEMA;
  schemaVersion: 1;
  dataset: string;
  environment: "demo";
  version: string;
  categories: { code: CategoryCode; label: string }[];
  products: (CatalogProduct & { images: (CatalogImage & { width: number; height: number })[] })[];
}

const ID_RE = /^DEMO-(RNG|EAR|NCK|SET)-\d{3}$/;
export const isRepdigit = (n: number) => Number.isInteger(n) && n >= 11 && /^(\d)\1+$/.test(String(n));
export const hasClaim = (s: string) => CLAIM_RE.test(s);

export function slugFor(id: string, title: string): string {
  const t = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return `${id.toLowerCase()}-${t}`.slice(0, 80).replace(/-$/, "");
}

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

/** Structural validation of an overrides file (no file access). */
export function validateOverrides(input: unknown): { issues: Issue[]; overrides: Overrides | null } {
  const issues: Issue[] = [];
  const err = (field: string, message: string) => issues.push({ severity: "error", field, message });
  if (!isObj(input)) {
    err("(root)", "Overrides must be a JSON object.");
    return { issues, overrides: null };
  }
  if (input.schema !== OVERRIDES_SCHEMA) err("schema", `Expected "${OVERRIDES_SCHEMA}".`);
  if (!SUPPORTED_VERSIONS.includes(input.schemaVersion as 1)) {
    err("schemaVersion", `Unsupported schemaVersion ${JSON.stringify(input.schemaVersion)}; supported: ${SUPPORTED_VERSIONS.join(", ")}.`);
    return { issues, overrides: null };
  }
  if (typeof input.dataset !== "string" || !/^[a-z0-9][a-z0-9-]{1,40}$/.test(input.dataset)) err("dataset", "dataset must be a short lowercase id (e.g. demo-2026-11).");
  for (const k of Object.keys(input)) if (!["schema", "schemaVersion", "dataset", "exclude", "lifestyle", "products"].includes(k)) issues.push({ severity: "warning", field: k, message: "Unknown field (typo?) - ignored." });

  const fileField = (v: unknown, field: string) => {
    if (typeof v !== "string" || !v.includes("/") || v.length > 300) err(field, "Must be a source path like \"Rings/Name.jpg\".");
  };
  if (input.exclude !== undefined) {
    if (!Array.isArray(input.exclude)) err("exclude", "Must be an array.");
    else input.exclude.forEach((e, i) => {
      if (!isObj(e)) return err(`exclude[${i}]`, "Must be {file, reason}.");
      fileField(e.file, `exclude[${i}].file`);
      if (typeof e.reason !== "string" || !e.reason.trim()) err(`exclude[${i}].reason`, "A reason is required.");
    });
  }
  if (input.lifestyle !== undefined) {
    if (!Array.isArray(input.lifestyle)) err("lifestyle", "Must be an array.");
    else input.lifestyle.forEach((f, i) => fileField(f, `lifestyle[${i}]`));
  }

  if (!Array.isArray(input.products) || input.products.length === 0) {
    err("products", "At least one product is required.");
    return { issues, overrides: null };
  }
  const ids = new Set<string>();
  input.products.forEach((p, i) => {
    const f = `products[${i}]`;
    if (!isObj(p)) return err(f, "Must be an object.");
    const id = p.id;
    if (typeof id !== "string" || !ID_RE.test(id)) err(`${f}.id`, "id must look like DEMO-RNG-001 (RNG, EAR, NCK or SET).");
    else {
      if (ids.has(id)) err(`${f}.id`, `Duplicate id ${id}.`);
      ids.add(id);
    }
    const cat = p.category as CategoryCode;
    if (!(typeof cat === "string" && cat in CATEGORIES)) err(`${f}.category`, `Unknown category; use ${Object.keys(CATEGORIES).join(", ")}.`);
    else if (typeof id === "string" && ID_RE.test(id) && id.split("-")[1] !== CATEGORIES[cat].prefix) err(`${f}.id`, `${id} does not match category "${cat}" (expected DEMO-${CATEGORIES[cat].prefix}-NNN).`);
    if (typeof p.title !== "string" || p.title.trim().length < 3 || p.title.length > 60) err(`${f}.title`, "Title must be 3-60 characters.");
    else if (hasClaim(p.title)) err(`${f}.title`, `"${p.title}" makes a material/gemstone/authenticity claim. Use visual words only (e.g. "Blue Halo Ring").`);
    else if (/\bdemo\b/i.test(p.title)) issues.push({ severity: "warning", field: `${f}.title`, message: "No need to write DEMO in the title; it is added on display." });
    if (!Array.isArray(p.tags)) err(`${f}.tags`, "tags must be an array.");
    else p.tags.forEach((t, j) => {
      if (typeof t !== "string" || !ALL_TAGS.has(t)) err(`${f}.tags[${j}]`, `Unknown tag ${JSON.stringify(t)}; tags are a fixed visual vocabulary.`);
    });
    if (typeof p.price !== "number" || !isRepdigit(p.price)) err(`${f}.price`, "Demo prices must be synthetic repeated-digit values (e.g. 1111, 22222).");
    if (!Array.isArray(p.images) || p.images.length === 0) err(`${f}.images`, "At least one source image is required.");
    else p.images.forEach((im, j) => fileField(im, `${f}.images[${j}]`));
    if (p.reviewNotes !== undefined) {
      if (!Array.isArray(p.reviewNotes)) err(`${f}.reviewNotes`, "reviewNotes must be an array of short strings.");
      else p.reviewNotes.forEach((n, j) => {
        if (typeof n !== "string" || !n.trim() || n.length > 200) err(`${f}.reviewNotes[${j}]`, "Each review note must be 1-200 characters.");
      });
    }
    for (const k of Object.keys(p)) if (!["id", "category", "title", "tags", "price", "images", "reviewNotes"].includes(k)) issues.push({ severity: "warning", field: `${f}.${k}`, message: "Unknown field (typo?) - ignored." });
  });
  if (issues.some((x) => x.severity === "error")) return { issues, overrides: null };
  return { issues, overrides: input as unknown as Overrides };
}

/** Strip local-only fields for serving. */
export function toPublic(catalog: Catalog): PublicCatalog {
  const byId = new Map(catalog.assets.map((a) => [a.id, a]));
  return {
    schema: catalog.schema,
    schemaVersion: catalog.schemaVersion,
    dataset: catalog.dataset,
    environment: catalog.environment,
    version: catalog.version,
    categories: (Object.keys(CATEGORIES) as CategoryCode[])
      .filter((c) => catalog.products.some((p) => p.category === c))
      .map((code) => ({ code, label: CATEGORIES[code].label })),
    products: catalog.products.map((p) => ({
      ...p,
      images: p.images.map((im) => ({ ...im, width: byId.get(im.asset)?.width ?? 0, height: byId.get(im.asset)?.height ?? 0 })),
    })),
  };
}
